package android.app;import android.content.*;import android.view.*;import java.util.*;public class AlertDialog implements DialogInterface {public static List<AlertDialog> shown=new ArrayList<>();public boolean dismissed,outside=true;public Window window=new Window();public void setCanceledOnTouchOutside(boolean v){outside=v;}public View body;public DialogInterface.OnClickListener positive,negative;public DialogInterface.OnDismissListener listener;public void dismiss(){if(dismissed)return;dismissed=true;if(listener!=null)listener.onDismiss(this);}public void setOnDismissListener(DialogInterface.OnDismissListener l){listener=l;}public void show(){shown.add(this);}public Window getWindow(){return window;}public static class Builder {AlertDialog d=new AlertDialog();public Builder(Context c){}public Builder setTitle(int i){return this;}public Builder setView(View v){d.body=v;return this;}public Builder setMessage(int i){return this;}public Builder setPositiveButton(int i,DialogInterface.OnClickListener l){d.positive=l;return this;}public Builder setNegativeButton(int i,DialogInterface.OnClickListener l){d.negative=l;return this;}public AlertDialog create(){return d;}public AlertDialog show(){d.show();return d;}}}
